/**
 * julIDE design tokens — the single source of truth for the visual system.
 *
 * Everything visual derives from this file: the CSS custom properties in
 * `src/styles/tokens.css` (generated by `bun run generate:tokens`), the Monaco
 * editor themes, and the xterm terminal palettes in `src/themes/themes.ts`.
 *
 * Before this existed, the chrome colors lived in App.css and the editor and
 * terminal palettes were hand-copied hex in separate files, so they drifted
 * apart silently. Nothing should hardcode a color outside this module.
 *
 * ── Direction: "Instrument" ──────────────────────────────────────────────
 * The ground is a cool blue-graphite (Julia's #4063D8 desaturated toward
 * black) rather than VS Code's neutral grey, which the old palette copied
 * verbatim.
 *
 * Accent colors are not decoration: they are Julia's own REPL prompt modes,
 * which every Julia user has already internalized.
 *
 *   julia>   green    running, success, tests passing
 *   pkg>     blue     packages, environments, informational
 *   help?>   yellow   docs, warnings, pending work
 *   shell>   red      errors, failures, destructive actions
 *            purple   identity, selection, focus, debugging
 */

/** A theme's full color surface. Every value is a `#rrggbb` literal. */
export interface Palette {
  /** Backgrounds, from deepest (editor) to most raised (dialogs). */
  surface: {
    canvas: string;
    chrome: string;
    panel: string;
    raised: string;
    hover: string;
    active: string;
    selected: string;
    /**
     * Backing plate for rendered plot output and embedded HTML.
     *
     * Deliberately white in *both* themes: Plots.jl and friends render onto a
     * transparent or white canvas with dark axes and text, so a dark plate
     * makes real figures unreadable. This is a content surface, not chrome.
     */
    plot: string;
  };
  /** 1px dividers. `strong` separates major regions, `default` everything else. */
  hairline: { default: string; strong: string };
  /** Foreground ramp. `inverse` reads against a filled mode color.
   *  Emitted as `--fg-*` so it never collides with the `--text-*` size scale. */
  fg: { hi: string; mid: string; lo: string; inverse: string };
  /** Julia's REPL prompt modes, used semantically throughout the UI. */
  mode: {
    run: string;
    pkg: string;
    help: string;
    shell: string;
    brand: string;
  };
  /** Julia syntax colors for Monaco. Kept separate so code can be tuned for
   *  reading density without dragging the whole UI palette with it. */
  syntax: {
    keyword: string;
    type: string;
    func: string;
    macro: string;
    symbol: string;
    string: string;
    number: string;
    comment: string;
    operator: string;
  };
  /** Elevation. Tinted with the theme's ink rather than pure black — the old
   *  pure-black shadows were unusably heavy in light mode. */
  elevation: { e1: string; e2: string; e3: string };
  /** Backdrop behind modals. */
  scrim: string;
  /** Editor selection and current-line. */
  editor: { selection: string; lineHighlight: string };
}

