/* ─────────────────────────────────────────────────────────────────────────
   Helpers
   ───────────────────────────────────────────────────────────────────────── */

/**
 * `#rrggbb` → `"r g b"` space-separated channels.
 *
 * Tints are composed as `rgb(var(--mode-run-rgb) / 0.16)` rather than with
 * `color-mix()`, which is not safe on the older WKWebView builds Tauri may run
 * against on macOS.
 */
export function hexToChannels(hex: string): string {
  const h = hex.replace("#", "");
  const n = parseInt(
    h.length === 3
      ? h
          .split("")
          .map((c) => c + c)
          .join("")
      : h,
    16,
  );
  return `${(n >> 16) & 255} ${(n >> 8) & 255} ${n & 255}`;
}

/** Monaco wants `rrggbb` with no leading `#` in its token rules. */
export function bare(hex: string): string {
  return hex.replace("#", "");
}

/** Blend two `#rrggbb` colors. `ratio` is how far to move from `a` toward `b`. */
export function mix(a: string, b: string, ratio: number): string {
  const channels = (hex: string) => hexToChannels(hex).split(" ").map(Number);
  const [r1, g1, b1] = channels(a);
  const [r2, g2, b2] = channels(b);
  return (
    "#" +
    [
      Math.round(r1 + (r2 - r1) * ratio),
      Math.round(g1 + (g2 - g1) * ratio),
      Math.round(b1 + (b2 - b1) * ratio),
    ]
      .map((v) => v.toString(16).padStart(2, "0"))
      .join("")
  );
}

/** Interactive hover for a mode color: lift toward white on dark, deepen on light. */
export function hoverOf(hex: string, isDark: boolean): string {
  return isDark ? mix(hex, "#ffffff", 0.16) : mix(hex, "#000000", 0.14);
}
